set -eu; CAP=/Users/michal/tracker-field-captures/2026-09-13-post-walk-v68; DB=$(find "$CAP" -maxdepth 3 -type f -name 'tracker_database' -print -quit); test -n "$DB"; export TRACKER_FIELD_DB="$DB"; python3 - <<'PY'
import os,sqlite3,statistics,json
from pathlib import Path
con=sqlite3.connect(f"file:{os.environ['TRACKER_FIELD_DB']}?mode=ro",uri=True); con.row_factory=sqlite3.Row
def med(x): return round(statistics.median(x),1) if x else None
mx=con.execute('select max(timestamp) from signal_samples').fetchone()[0]; start=mx-3*60*60*1000
ts=[int(r[0]) for r in con.execute('select timestamp from follow_me_observations where userMoved=1 and timestamp>=? order by timestamp',(start,))]
segs=[]
if ts:
 a=p=ts[0]
 for x in ts[1:]:
  if x-p>180000: segs.append((a,p)); a=x
  p=x
 segs.append((a,p))
walk=max([s for s in segs if s[1]-s[0]>=300000],key=lambda s:s[1]-s[0]); wa,wb=walk; total=max(1,int((wb-wa)//30000)+1)
print('WALK',round((wb-wa)/60000,1),'min')
# Metadata cache
dev={str(r['fingerprint']):r for r in con.execute('select * from devices')}
def meta(fp):
 r=dev.get(fp);
 if not r:return {}
 return {'name':str(r['lastDeviceName'] or ''),'type':str(r['deviceType'] or ''),'vendor':str(r['vendorName'] or ''),'model':str(r['predictedModel'] or ''),'beacon':str(r['beaconType'] or ''),'score':float(r['followingScore'] or 0),'status':str(r['trackingStatus'] or ''),'paired':bool(r['isPaired'])}
rows=list(con.execute('select * from signal_samples where timestamp between ? and ? order by timestamp',(wa,wb)))
g={}
for r in rows:g.setdefault(str(r['deviceFingerprint']),[]).append(r)
def st(rs):
 t=[int(r['timestamp']) for r in rs]; rr=[int(r['rssi']) for r in rs]; bins={int((x-wa)//30000) for x in t}; return {'samples':len(t),'spanMin':round((max(t)-min(t))/60000,1),'medianRssi':med(rr),'coverage':round(len(bins)/total,3),'startMin':round((min(t)-wa)/60000,1),'endMin':round((max(t)-wa)/60000,1),'bins':bins}
allr=[]
for fp,rs in g.items():
 s=st(rs); m=meta(fp); allr.append((s['coverage'],s['samples'],fp,m,s))
for i,(_,_,fp,m,s) in enumerate(sorted(allr,reverse=True)[:30],1):
 o={**m,**{k:v for k,v in s.items() if k!='bins'}}; print('TOP',json.dumps({'id':f'D{i:02d}',**o},sort_keys=True))
# Wearables/paired candidates even if classifier metadata is weak.
wear=[]
for cov,n,fp,m,s in allr:
 txt=' '.join(str(m.get(k,'')) for k in ['name','type','vendor','model','beacon']).lower()
 if m.get('paired') or m.get('type','').upper() in {'WATCH','WEARABLE','FITNESS'} or any(x in txt for x in ['garmin','forerunner']): wear.append((cov,n,fp,m,s))
for i,(_,_,fp,m,s) in enumerate(sorted(wear,reverse=True)[:25],1): print('WEAR',json.dumps({'id':f'W{i:02d}',**m,**{k:v for k,v in s.items() if k!='bins'}},sort_keys=True))
# Tracker fragments and greedy sequential chains.
fr=[]
for cov,n,fp,m,s in allr:
 txt=' '.join(str(m.get(k,'')) for k in ['name','type','vendor','model','beacon']).lower()
 if any(x in txt for x in ['find my','findmy','airtag','tracker','smarttag','tile']) or m.get('type','').upper() in {'TRACKER','TAG','AIRTAG','TILE','SAMSUNG_TAG'}:
  if s['samples']>=5: fr.append({'fp':fp,**m,**s})
fr.sort(key=lambda x:(x['startMin'],x['endMin']))
# Label fragments by individual coverage rank for readable output.
rank={x['fp']:f'F{i+1:02d}' for i,x in enumerate(sorted(fr,key=lambda z:(z['coverage'],z['samples']),reverse=True))}
for x in sorted(fr,key=lambda z:(z['coverage'],z['samples']),reverse=True)[:20]: print('FRAG',json.dumps({'id':rank[x['fp']],**{k:v for k,v in x.items() if k not in {'fp','bins'}}},sort_keys=True))
chains=[]
for seed in fr:
 chain=[seed]; used={seed['fp']}; cur=seed
 while True:
  cand=[]
  for x in fr:
   if x['fp'] in used: continue
   gap=x['startMin']-cur['endMin']
   if -0.5<=gap<=3.0 and abs((x['medianRssi'] or -100)-(cur['medianRssi'] or -100))<=12:
    cand.append((gap,-x['samples'],x))
  if not cand: break
  x=sorted(cand,key=lambda z:(abs(z[0]),z[1]))[0][2]; chain.append(x); used.add(x['fp']); cur=x
 bins=set().union(*(x['bins'] for x in chain));
 if len(chain)>=2: chains.append((len(bins)/total,sum(x['samples'] for x in chain),chain))
seen=set(); out=[]
for cov,n,ch in sorted(chains,key=lambda z:(z[0],z[1]),reverse=True):
 ids=tuple(rank[x['fp']] for x in ch)
 key=frozenset(ids)
 if key in seen: continue
 seen.add(key); out.append((cov,n,ch,ids))
 if len(out)>=10: break
for i,(cov,n,ch,ids) in enumerate(out,1): print('CHAIN',json.dumps({'id':f'C{i:02d}','fragments':ids,'coverage':round(cov,3),'samples':n,'startMin':round(min(x['startMin'] for x in ch),1),'endMin':round(max(x['endMin'] for x in ch),1),'medianRssi':[x['medianRssi'] for x in ch]},sort_keys=True))
PY

